{
    "id": "opencode",
    "displayName": "OpenCode (CLI)",
    "homepage": "https://opencode.ai/",
    "docs": "https://opencode.ai/docs",
    "github": "https://github.com/anomalyco/opencode",
    "kind": "cli",
    "platforms": ["windows", "macos", "linux"],
    "install": {
        "curl (macOS / Linux — recommended)": "curl -fsSL https://opencode.ai/v2/install | bash",
        "curl (Windows — Git Bash / MSYS2 alternative)": "curl -fsSL https://opencode.ai/v2/install | bash",
        "brew (macOS / Linux)": "brew install anomalyco/tap/opencode-v2",
        "note": "OpenCode v2 uses the scoped npm package `@opencode/cli` and the official v2 shell installer. The installer resolves the current platform package from OpenCode's update API and installs the binary under ~/.opencode/bin. On native Windows, prefer npm; the curl command requires Git Bash / MSYS2 / Cygwin and must not be piped to PowerShell `iex`. Do not use the legacy Scoop or Chocolatey recipes for a v2 request because the official v2 download page does not list them as v2 channels. Verify with `opencode --version` after refreshing PATH.",
        "npm (all platforms; preferred for native Windows)": "npm install -g @opencode/cli",
        "bun (all supported platforms)": "bun install -g --trust @opencode/cli"
    },
    "install_flow": {
        "summary": "macOS/Linux: official v2 shell installer or package manager; native Windows: scoped npm package → verify",
        "agent_steps": [
            "Detect OS and architecture first.",
            "macOS / Linux: prefer `curl -fsSL https://opencode.ai/v2/install | bash` (installs the v2 prebuilt binary to ~/.opencode/bin, no Node needed). On network failure, fall back to `brew install anomalyco/tap/opencode-v2` then npm.",
            "Windows: use `npm install -g @opencode/cli` with an installed Node/npm. The official v2 shell installer is an alternative only under Git Bash / MSYS2 / Cygwin; do not pipe it into PowerShell `iex`. Do not substitute the legacy Scoop or Chocolatey recipes for a v2 request.",
            "npm path (all platforms): check Node/npm, then run `npm install -g @opencode/cli`. If a registry download fails, diagnose it and, with the user's mirror fallback selected, use `npm install -g @opencode/cli --registry=https://registry.npmmirror.com --fetch-timeout=600000`.",
            "Verify with `opencode --version`. On Windows if the command isn't found after an npm install, the shim is at %APPDATA%\\npm\\opencode.cmd — restart the shell so PATH picks it up.",
            "If an earlier npm install timed out, DO NOT immediately retry: a still-running node/postinstall may be writing to the same node_modules and a concurrent retry corrupts it. Let the runner kill the process tree first (handled automatically on timeout), or manually confirm no node/npm process is running before retrying."
        ],
        "tell_user": [
            "Which install method was used (curl / scoop / choco / release binary / npm)",
            "On Windows the npm global shim is %APPDATA%\\npm\\opencode.cmd — restart the shell if `opencode` isn't found",
            "Verify command: `opencode --version`"
        ]
    },
    "network_requirements": {
        "test_urls": [
            "https://opencode.ai",
            "https://registry.npmjs.org/@opencode%2fcli",
            "https://github.com/anomalyco/opencode"
        ],
        "mirrors": {
            "npm (China)": "npm install -g @opencode/cli --registry=https://registry.npmmirror.com --fetch-timeout=600000"
        },
        "blocked_regions": {
            "zh-CN": "The v2 Bash installer resolves and downloads the platform package through OpenCode's update service and the npm registry. If those hosts are unreachable, use the user's configured proxy or approved npm registry mirror; verify the download instead of assuming regional access."
        }
    },
    "first_run": {
        "description": "On first launch `opencode` opens a TUI. To use your own provider, add an OpenAI-compatible provider block in the config file, or run `/connect` and pick a provider. OpenRouter, Anthropic, and any OpenAI-compatible endpoint are supported.",
        "config_global": "$OPENCODE_CONFIG_DIR/opencode.json(c), otherwise $XDG_CONFIG_HOME/opencode/opencode.json(c), otherwise ~/.config/opencode/opencode.json(c)",
        "config_project": "opencode.json",
        "verify": "opencode --version"
    },
    "identity_guard": {
        "description": "OpenCode v2 is Anomaly's open-source CLI coding agent (github.com/anomalyco/opencode, branch `v2`), npm package `@opencode/cli`. It is DIFFERENT from Claude Code (Anthropic, @anthropic-ai/claude-code), Codex CLI (OpenAI, @openai/codex), and the OpenCode Desktop GUI app — a separate EchoBird tool. The old v1 npm package was `opencode-ai`; for v2 use the exact package name `@opencode/cli`."
    }
}

{
    "id": "opencodedesktop",
    "displayName": "OpenCode Desktop",
    "homepage": "https://opencode.ai/",
    "docs": "https://opencode.ai/docs",
    "github": "https://github.com/anomalyco/opencode",
    "kind": "desktop_app",
    "platforms": ["windows", "macos", "linux"],
    "install": {
        "macos_brew_cask": "brew install --cask opencode-desktop",
        "macos_download": "Open https://opencode.ai/download in the browser, click the macOS download (.dmg, Apple Silicon or Intel). Saves to ~/Downloads by default.",
        "windows_download": "Open https://opencode.ai/download in the browser, click the Windows (x64) download — a one-click NSIS .exe installer. Saves to %USERPROFILE%\\Downloads by default.",
        "linux_download": "Open https://opencode.ai/download in the browser, download the x64 .deb / .rpm and install it.",
        "note": "Official v2 GUI desktop application (Electron) with a bundled OpenCode CLI. It shares the OpenCode global config directory with the standalone CLI: OPENCODE_CONFIG_DIR when set, otherwise $XDG_CONFIG_HOME/opencode, otherwise ~/.config/opencode. A model configured for one therefore applies to both. Always tell the user the download location and ask them to run the installer themselves."
    },
    "install_flow": {
        "summary": "Download installer -> user double-clicks -> installer finishes (Windows is a one-click NSIS installer; macOS/Linux follow the wizard or drag-to-Applications)",
        "agent_steps": [
            "Detect OS first.",
            "macOS: prefer `brew install --cask opencode-desktop` when Homebrew is available; otherwise download the .dmg from https://opencode.ai/download and open it.",
            "Windows / Linux: download the installer from https://opencode.ai/download to the Downloads folder.",
            "After the download finishes, tell the user the EXACT file path.",
            "Open the installer (`Start-Process` on Windows, `open` on macOS).",
            "Tell the user to follow the installer to finish; the Windows NSIS build installs in one click with no directory prompt.",
            "Do NOT try to automate the GUI wizard."
        ],
        "tell_user": [
            "Download location (full path)",
            "That the installer was opened",
            "That OpenCode Desktop shares model config with the OpenCode CLI"
        ]
    },
    "identity_guard": {
        "description": "OpenCode Desktop is the official GUI app for OpenCode v2 (the open-source AI coding agent by Anomaly). It is DIFFERENT from the standalone OpenCode CLI (npm `@opencode/cli`), though the desktop package bundles a CLI internally. Both can coexist and share the same global OpenCode config directory, so a model set for one applies to both."
    },
    "network_requirements": {
        "test_urls": ["https://opencode.ai", "https://github.com"],
        "mirrors": {}
    }
}

// Components barrel export
export { ModelCard, ModelCardSkeleton, getModelIcon } from './cards';
export type { ModelCardProps } from './cards';

export { NavItem } from './NavItem';
export type { NavItemProps } from './NavItem';

export * from './MiniSelect';
export * from './ModelIdCombobox';
export * from './Toast';
export * from './ConfirmDialog';
export { Sidebar } from './Sidebar';
export type { PageType } from './Sidebar';
export * from './SettingsDialog';

// Lightweight i18n entry — translation loader
// Tool names, API terms, and brand names stay in English

import { en } from './en';
import type { Translations } from './types';

export type TKey = keyof Translations;
export type { Translations };
export { en };

const loadedLocales: Record<string, Partial<Translations>> = { en };

const localeLoaders: Record<string, () => Promise<{ default: Partial<Translations> }>> = {
  'zh-Hans': () => import('./zh-Hans'),
  'zh-Hant': () => import('./zh-Hant'),
  ja: () => import('./ja'),
};

export function resolveLocale(tag: string): string {
  if (!tag) return 'en';
  // Traditional Chinese: TW / HK / MO / explicit Hant tag
  if (/^zh[-_](TW|HK|MO|Hant)/i.test(tag)) return 'zh-Hant';
  // Anything else starting with zh → Simplified
  if (/^zh/i.test(tag)) return 'zh-Hans';
  if (/^ja/i.test(tag)) return 'ja';
  return 'en';
}

export function detectLocale(): string {
  try {
    const saved = localStorage.getItem('echobird-locale');
    if (saved) return resolveLocale(saved);
  } catch {
    /* ignore */
  }
  const lang = typeof navigator !== 'undefined' ? navigator.language || 'en' : 'en';
  return resolveLocale(lang);
}

export async function loadLocale(locale: string): Promise<void> {
  if (loadedLocales[locale]) return;
  const loader = localeLoaders[locale];
  if (!loader) return;
  try {
    const mod = await loader();
    if (mod?.default) loadedLocales[locale] = mod.default;
  } catch {
    // Silently fall back to English
  }
}

export function translate(key: TKey, locale: string): string {
  const dict = loadedLocales[locale] || en;
  return (
    (dict as Record<string, string>)[key as string] ||
    (en as Record<string, string>)[key as string] ||
    (key as string)
  );
}

// Cards barrel export
export { ModelCard, ModelCardSkeleton, getModelIcon } from './ModelCard';
export type { ModelCardProps } from './ModelCard';

export { ChatBubble } from './ChatBubble';
export type { ChatBubbleProps, BubbleChip, BubbleRole } from './ChatBubble';
export { TerminalStatusBar } from './TerminalStatusBar';
export { ToolCallCard } from './ToolCallCard';
export type { ToolCallCardProps } from './ToolCallCard';

export { AiCareerMain, AiCareerTitleActions } from './AiCareerMain';
export { AiCareerPanel } from './AiCareerPanel';
export { AiCareerFamilyPanel } from './AiCareerFamilyPanel';

import Gio from 'gi://Gio';
import Shell from 'gi://Shell';
import { Extension } from 'resource:///org/gnome/shell/extensions/extension.js';
import * as Main from 'resource:///org/gnome/shell/ui/main.js';

const interfaceXml = `<node>
  <interface name="com.echobird.IconBridge">
    <method name="GetActiveApp">
      <arg name="app_id" type="s" direction="out"/>
      <arg name="window_id" type="s" direction="out"/>
    </method>
  </interface>
</node>`;

export default class EchoBirdIcons extends Extension {
  enable() {
    this._bridge = Gio.DBusExportedObject.wrapJSObject(interfaceXml, this);
    this._bridge.export(Gio.DBus.session, '/org/gnome/Shell/Extensions/EchoBird');
  }

  GetActiveApp() {
    const window = global.display.get_focus_window();
    if (!window || Main.sessionMode.isLocked) return ['', ''];
    const app = Shell.WindowTracker.get_default().get_window_app(window);
    return [app?.get_id() ?? '', String(window.get_stable_sequence())];
  }

  disable() {
    this._bridge?.unexport();
    this._bridge = null;
  }
}
